function createTemplate(id: string, width: 48 | 56 | 96, alpha: readonly number[]): WatermarkTemplate {
  return {
    id,
    width,
    height: width,
    alpha: Float32Array.from(alpha),
    color: [255, 255, 255],
    blendMode: 'normal-alpha',
    version: 'calibrated-examples-2026-05',
    source: TEMPLATE_SOURCE,
    provider: 'gemini',
    notes: TEMPLATE_NOTES
  };
}

export function createRealGeminiTemplates(): WatermarkTemplate[] {
  return [
    createTemplate('gemini-visible-white-48', 48, GEMINI_REAL_ALPHA_48),
    createTemplate('gemini-visible-white-56', 56, GEMINI_REAL_ALPHA_56),
    createTemplate('gemini-visible-white-96', 96, GEMINI_REAL_ALPHA_96)
  ];
}
